const readable=value=>value && value!=='unknown'?String(value):t('noInfo');
const number=value=>value===undefined||value===null?t('noInfo'):Number(value).toLocaleString(lang==='tr'?'tr-TR':'en-US');
const date=value=>{if(!value||value==='unknown')return t('noInfo');const parsed=new Date(value);return Number.isNaN(parsed.getTime())?t('noInfo'):new Intl.DateTimeFormat(lang==='tr'?'tr-TR':'en-US',{day:'numeric',month:'short',year:'numeric'}).format(parsed);};
const shortProject=value=>value&&value!=='unknown'?value.split(/[\\/]/).filter(Boolean).pop()||t('noInfo'):t('noInfo');
function showError(error){technicalError=String(error?.message||error);const lower=technicalError.toLowerCase();let key='errorGeneric';if(/conflict|existing file differs|unchanged_owned|çakış/i.test(lower))key='errorConflict';else if(/since preview|changed after save|preview required/i.test(lower))key='errorStale';else if(/invalid|unknown|unsupported|must be|toml/i.test(lower))key='errorInput';recordActivity('error',{errorKey:key,technical:technicalError});document.querySelector('.activity').scrollIntoView({behavior:'smooth',block:'center'});return key;}
async function api(path,payload){const options=payload===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':token},body:JSON.stringify(payload)};const response=await fetch(path,options);let data;try{data=await response.json();}catch(_){throw Error('Response could not be read');}if(!response.ok){const error=Error(data.error||'Request failed');error.partial=data.partial;throw error;}return data;}
function recordActivity(key,extra={}){activityState=key;activityHistory.unshift({key,time:new Date(),...extra});activityHistory=activityHistory.slice(0,5);renderActivity();}
function renderActivity(){const event=activityHistory[0]||{key:activityState};$('activity-title').textContent=t(event.key);$('activity-next').textContent=event.key==='error'?t(event.errorKey||'errorGeneric')+' '+t('errorNext'):t(event.key==='saved'?'savedNext':event.key==='restored'?'restoredNext':event.key==='previewReady'?'previewNext':event.key==='previewing'?'previewingNext':['saving','restoring'].includes(event.key)?'savingNext':event.key==='usageRefreshed'?'usageNext':event.key==='modelsRefreshed'?'modelsRefreshedNext':'settingsNext');$('activity-list').replaceChildren();for(const item of activityHistory){const li=make('li','',`${new Intl.DateTimeFormat(lang==='tr'?'tr-TR':'en-US',{hour:'2-digit',minute:'2-digit'}).format(item.time)} · ${t(item.key)}`);$('activity-list').append(li);}const old=$('error-details');if(old)old.remove();if(event.key==='error'){const details=make('details','technical');details.id='error-details';details.append(make('summary','',t('errorDetails')),make('p','',event.technical||technicalError));$('activity-next').after(details);}}
function renderStatic(){document.documentElement.lang=lang;document.title=t('title');$('language').value=lang;for(const node of document.querySelectorAll('[data-i18n]'))node.textContent=t(node.dataset.i18n);for(const node of document.querySelectorAll('[data-i18n-aria]'))node.setAttribute('aria-label',t(node.dataset.i18nAria));$('team-decrease').setAttribute('aria-label',t('teamDecrease'));$('team-increase').setAttribute('aria-label',t('teamIncrease'));$('save').textContent=t(config?.installed?'teamSave':'teamInstalled');if(saveResultKey)$('save-result').textContent=t(saveResultKey);renderUninstall();renderActivity();updateRoleLabels();renderTeam();renderTaskCards();renderModelSource();renderAdvisoryStatus();renderOtherEffect();renderSummary();renderPreview();renderUsage();renderOrchestra();renderWork();}
function roleValues(){const result={};for(const card of $('roles').children)result[card.dataset.role]={model:card.querySelector('select[data-kind=model]').value,effort:card.querySelector('select[data-kind=effort]').value};return result;}
function equalRoles(a,b){return Object.keys(ROLE_KEYS).every(role=>a[role]?.model===b[role]?.model&&a[role]?.effort===b[role]?.effort);}
function matchingPreset(roles){if(!config)return null;return Object.keys(config.presets).find(key=>key!=='custom'&&equalRoles(roles,config.presets[key]))||'custom';}
function profileLabel(roles,installed=true){return installed?t(PROFILE_KEYS[matchingPreset(roles)]||'customTitle'):t('notSaved');}
function selectedLabel(){return t(manualOverride?'customTitle':PROFILE_KEYS[selectedPreset]||'customTitle');}
function roleChangeCount(values){return Object.keys(ROLE_KEYS).filter(role=>config.roles[role]?.model!==values[role]?.model||config.roles[role]?.effort!==values[role]?.effort).length;}
function plainChanges(values,cap){if(!config.installed)return t('choiceWillApply')+' '+t('teamPreview',teamState.length)+(JSON.stringify(advisoryState)!==JSON.stringify(config.advisory_selection)?' · '+t('advisoryChanged'):'');const parts=[];const changed=roleChangeCount(values);if(changed)parts.push(t('roleChanges',changed));if(cap!==config.concurrency)parts.push(t('capChange'));if(teamState.length!==config.team.length)parts.push(t('teamCountExact',config.team.length,teamState.length));if(JSON.stringify(teamState)!==JSON.stringify(config.team))parts.push(t('teamChanged'));if(JSON.stringify(advisoryState)!==JSON.stringify(config.advisory_selection))parts.push(t('advisoryChanged'));return parts.length?parts.join(' · '):t('previewNoChanges');}
function renderSummary(){if(!config)return;const pending=roleValues(),cap=Number($('concurrency').value)||config.concurrency;$('current-summary').textContent=config.installed?t(PROFILE_KEYS[config.saved_preset||matchingPreset(config.roles)]||'customTitle'):t('notSaved');$('current-detail').textContent=config.installed?(matchingPreset(config.roles)==='custom'&&!config.saved_preset?t('customDetail')+' · ':'')+t('teamPreview',config.team.length)+' · '+t('helpers',config.concurrency):t('notSavedDetail');$('pending-summary').textContent=selectedLabel();$('pending-detail').textContent=plainChanges(pending,cap);}
function invalidate(){previewVersion++;previewId=null;lastPreview=null;lastSelection=null;saveResultKey='';$('preview').hidden=true;$('save').disabled=true;$('save-status').textContent='';$('save-result').hidden=true;renderSummary();}
function formatTemplate(key,values){return t(key).replace(/\{(\w+)\}/g,(_,field)=>String(values[field]??''));}
function modelEntry(id){return catalog?.models.find(item=>item.id===id);}
const DEFAULT_TEAM_DUTIES=['explorer','researcher','implementer','reviewer','verifier','fast_lookup','qa_operator','failure_analyst','advisor'];
function defaultTeam(count,roles){return Array.from({length:count},(_,index)=>{const duty=DEFAULT_TEAM_DUTIES[index%DEFAULT_TEAM_DUTIES.length],choice=roles?.[duty]||config?.presets.focused[duty];return {slot:`team_slot_${String(index+1).padStart(2,'0')}`,duty,model:choice.model,effort:choice.effort,title:''};});}
const MODEL_CHOICES={astra:['gpt-6-astra'],sol:['gpt-6.1-sol'],luna:['gpt-6-luna']};
function recommendedModel(family){const ids=MODEL_CHOICES[family],entries=catalog?.models||[];return ids.map(id=>entries.find(item=>item.id===id)).find(item=>item?.origin==='local_cli')?.id||ids.find(id=>entries.some(item=>item.id===id))||ids[0];}
function recommendedEffort(model,wanted){const choices=modelEntry(model)?.efforts||[];if(!choices.length||choices.includes(wanted))return wanted;const order=config?.efforts||['low','medium','high','xhigh','max','ultra'];return choices.reduce((best,item)=>Math.abs(order.indexOf(item)-order.indexOf(wanted))<Math.abs(order.indexOf(best)-order.indexOf(wanted))?item:best,choices[0]);}
function recommendationFor(duty,style,task){const template=TASK_TEMPLATES[task],deep=template?.deep.includes(duty),lightTask=['research','data'].includes(task);let family,effort;if(style==='focused'){family=['fast_lookup','explorer'].includes(duty)?'luna':'sol';effort=deep?'high':'medium';}else if(style==='quality'){family=['fast_lookup','explorer'].includes(duty)?'luna':'astra';effort=deep?'xhigh':'high';}else{family=['fast_lookup','explorer'].includes(duty)?'luna':duty==='owner'&&!lightTask?'astra':'sol';effort=deep?'high':'medium';}if(duty==='owner'){family=style==='focused'||(style==='balanced'&&lightTask)?'sol':'astra';effort=style==='quality'?'high':style==='focused'?'medium':deep?'high':'medium';}const model=recommendedModel(family);return {model,effort:recommendedEffort(model,effort)};}
function recommendedRoles(style,task){const roles={};for(const role of Object.keys(ROLE_KEYS))roles[role]=recommendationFor(role,style,task);return roles;}
function renderTaskCards(){const holder=$('task-cards');holder.replaceChildren();if(!config)return;for(const [id,template] of Object.entries(TASK_TEMPLATES)){const button=make('button','task-card'+(selectedTask===id?' selected':''));button.type='button';button.dataset.task=id;button.setAttribute('aria-pressed',String(selectedTask===id));button.append(make('strong','',t(template.key)),make('span','',t('taskGeneralHelp')));holder.append(button);}renderDraftSummary();}
function renderDraftSummary(){const note=$('task-draft-summary');if(!note)return;const owner=roleValues().owner,names=teamState.slice(0,5).map((item,index)=>`${index+1} ${t(ROLE_KEYS[item.duty])}: ${item.model} · ${effortLabel(item.effort)}`);note.textContent=selectedTask?t('draftReady',t(TASK_TEMPLATES[selectedTask].key),t(PROFILE_KEYS[selectedPreset]||'customTitle'),teamState.length,Number($('concurrency').value),owner?.model+' · '+effortLabel(owner?.effort))+' '+names.join('; ')+(teamState.length>5?` · +${teamState.length-5}`:'')+(manualOverride?' '+t('draftManual'):''):t('draftEmpty');$('undo-draft').disabled=!draftSnapshot;}
function captureDraft(){return {task:selectedTask,preset:selectedPreset,manual:manualOverride,roles:roleValues(),team:teamState.map(item=>({...item})),count:$('team-count').value,concurrency:$('concurrency').value,slot:selectedTeamSlot,page:teamPage};}
function chooseTask(id){const template=TASK_TEMPLATES[id];if(!template||!config)return;draftSnapshot=captureDraft();selectedTask=id;manualOverride=false;selectedPreset=template.style;const roles=recommendedRoles(template.style,id);syncPreset();fillRoles(roles);teamState=template.duties.map((duty,index)=>({slot:`team_slot_${String(index+1).padStart(2,'0')}`,duty,...recommendationFor(duty,template.style,id),title:''}));$('team-count').value=teamState.length;$('concurrency').value=template.concurrency;selectedTeamSlot='owner';teamPage=0;renderTeam();renderTaskCards();renderOtherEffect();invalidate();}
function undoDraft(){if(!draftSnapshot)return;const draft=draftSnapshot;draftSnapshot=null;selectedTask=draft.task;selectedPreset=draft.preset;manualOverride=draft.manual;teamState=draft.team;$('team-count').value=draft.count;$('concurrency').value=draft.concurrency;selectedTeamSlot=draft.slot;teamPage=draft.page;syncPreset();fillRoles(draft.roles);renderTeam();renderTaskCards();renderOtherEffect();invalidate();$('task-draft-summary').textContent=t('draftUndone');}
function teamModelOptions(select,chosen,saved){select.replaceChildren();for(const item of catalog?.models||[])select.append(new Option(item.label+' · '+t(item.origin==='local_cli'?'modelLocalBadge':'modelDocsBadge'),item.id));if(chosen&&!modelEntry(chosen))select.prepend(new Option(chosen+' · '+t(saved?'savedModelNotListed':'unlistedSelection'),chosen));select.value=chosen;}
function teamEffortOptions(select,model,chosen){select.replaceChildren();const efforts=modelEntry(model)?.efforts?.length?modelEntry(model).efforts:config.efforts;for(const effort of efforts){const key='effort'+effort[0].toUpperCase()+effort.slice(1);select.append(new Option(t(key),effort));}if(chosen&&!efforts.includes(chosen))select.append(new Option(chosen+' · '+t('effortUnlisted'),chosen));select.value=chosen;}
function teamField(label,node){const holder=make('label');holder.append(make('span','',label),node);return holder;}
