function updateSettingsMotionHint(){if($('team-motion-hint'))$('team-motion-hint').textContent=t('teamMotionHint');}
function syncConductorPhase(svg){if(!svg)return;svg.classList.add('is-conducting');const elapsed=performance.now()-conductorMotionEpoch;for(const part of svg.querySelectorAll('.baton-arm,.music-note'))for(const animation of part.getAnimations())if(animation.animationName==='baton-swing'||animation.animationName==='note-float')animation.currentTime=elapsed;}
