function teamChip(value,label,selected,field){const chip=make('button','team-chip'+(selected?' selected':''),label);chip.type='button';chip.dataset.field=field;chip.dataset.value=value;chip.setAttribute('aria-pressed',String(selected));return chip;}
function renderTeamInspector(){const holder=$('team-inspector');holder.replaceChildren();if(!config)return;const chief=selectedTeamSlot==='owner',index=teamState.findIndex(item=>item.slot===selectedTeamSlot);if(!chief&&index<0){selectedTeamSlot=teamState[0]?.slot||'owner';return renderTeamInspector();}const item=chief?roleValues().owner:teamState[index],heading=chief?t('teamInspectChief'):t('teamInspectHelper',index+1);holder.append(make('p','team-inspector-kicker',t('teamSelected')),make('h4','',heading));if(chief)holder.append(make('p','team-inspector-help',t('teamChiefDuty')));else{const dutyGroup=make('div','team-choice-group');dutyGroup.append(make('strong','',t('teamDuty')));const chips=make('div','team-chip-grid duty-chips');for(const duty of config.team_duties)chips.append(teamChip(duty,t(ROLE_KEYS[duty]||'helper'),duty===item.duty,'duty'));dutyGroup.append(chips);holder.append(dutyGroup);}
const modelGroup=make('div','team-choice-group');modelGroup.append(make('strong','',t('model')));const known=new Set(),chips=make('div','team-chip-grid model-chips');for(const entry of catalog?.models||[]){known.add(entry.id);const badge=t(entry.origin==='local_cli'?'modelLocalBadge':'modelDocsBadge'),chip=teamChip(entry.id,entry.label,entry.id===item.model,'model');chip.append(make('small','team-chip-provenance',badge));chip.setAttribute('aria-label',`${entry.label}: ${badge}`);chips.append(chip);}if(item.model&&!known.has(item.model)){const chip=teamChip(item.model,item.model,true,'model');chip.append(make('small','team-chip-provenance',t('modelSavedBadge')));chips.prepend(chip);}modelGroup.append(chips);if(modelEntry(item.model)?.origin==='documentation')modelGroup.append(make('p','model-warning',t('teamModelWarning')));holder.append(modelGroup);
const effortGroup=make('div','team-choice-group');effortGroup.append(make('strong','',t('depth')));const efforts=modelEntry(item.model)?.efforts?.length?modelEntry(item.model).efforts:config.efforts;const effortChips=make('div','team-chip-grid effort-chips');for(const effort of efforts)effortChips.append(teamChip(effort,effortLabel(effort),effort===item.effort,'effort'));if(item.effort&&!efforts.includes(item.effort))effortChips.append(teamChip(item.effort,effortLabel(item.effort)+' · '+t('effortUnlisted'),true,'effort'));effortGroup.append(effortChips);holder.append(effortGroup);if(!chief){const label=make('label','team-title-label');label.append(make('span','',t('teamTitle')));const title=make('input');title.id='team-title';title.maxLength=48;title.placeholder=t('teamTitlePlaceholder');title.value=item.title;label.append(title);holder.append(label);}}
function renderTeam(){const holder=$('team-slots');if(!holder||!config)return;$('team-style-current').textContent=t(PROFILE_KEYS[selectedPreset]||'customTitle');$('team-decrease').disabled=Number($('team-count').value)<=1;$('team-increase').disabled=Number($('team-count').value)>=50;holder.replaceChildren();const chief=make('div','team-stage-chief');chief.append(teamActor('owner',roleValues().owner,0));holder.append(chief);const selected=teamState.find(item=>item.slot===selectedTeamSlot),intro=make('div','team-stage-helper-intro');intro.append(make('strong','',t('helpersHeading')),make('p','',selected?t(DUTY_DESCRIPTIONS[selected.duty]||'helperPickHint'):t('helperPickHint')));holder.append(intro);const pages=Math.max(1,Math.ceil(teamState.length/10));teamPage=Math.min(teamPage,pages-1);if(pages>1){const navigation=make('div','team-pages');const back=make('button','secondary','←');back.type='button';back.disabled=teamPage===0;back.setAttribute('aria-label',t('teamPrevious'));back.addEventListener('click',()=>{teamPage--;renderTeam();});const next=make('button','secondary','→');next.type='button';next.disabled=teamPage>=pages-1;next.setAttribute('aria-label',t('teamNext'));next.addEventListener('click',()=>{teamPage++;renderTeam();});navigation.append(back,make('span','',t('teamPage',teamPage+1,pages)),next);holder.append(navigation);}const helpers=make('div','team-stage-helpers');for(const [index,item] of teamState.entries()){if(index>=teamPage*10&&index<(teamPage+1)*10)helpers.append(teamActor(item.slot,item,index));}holder.append(helpers);renderTeamInspector();syncSettingsConductorMotion();}
function resizeTeam(){const count=Number($('team-count').value);if(!Number.isInteger(count)||count<1||count>50||count===teamState.length)return;const defaults=defaultTeam(count,roleValues());teamState=defaults.map((item,index)=>teamState[index]||item);if(selectedTeamSlot!=='owner'&&!teamState.some(item=>item.slot===selectedTeamSlot))selectedTeamSlot=teamState.at(-1)?.slot||'owner';teamPage=Math.min(teamPage,Math.ceil(count/10)-1);manualOverride=Boolean(selectedTask);renderTeam();renderDraftSummary();invalidate();}
function applyPresetToTeam(preset){const values=['focused','balanced','quality'].includes(preset)?recommendedRoles(preset,selectedTask):config.presets[preset];teamState=teamState.map(item=>({...item,model:values[item.duty].model,effort:values[item.duty].effort}));renderTeam();}
function renderModelSource(){if(!catalog)return;const dateValue=catalog.discovery==='local_cli'?catalog.checked_at:catalog.documentation_reviewed_at;const key=catalog.discovery==='local_cli'?'modelSourceRuntime':'modelSourceFallback';$('model-source').textContent=formatTemplate(key,{date:date(dateValue)});}
const ADVISER_LABELS={'claude-fable-5-1':'Claude Fable 5.1','claude-opus-5-5':'Claude Opus 5.5','claude-sonnet-5-5':'Claude Sonnet 5.5','claude-haiku-4-5-20251001':'Claude Haiku 4.5','deepseek-flash':'DeepSeek Flash'};
function adviserLabel(choice){return choice.provider==='none'?t('advisoryNoProvider'):choice.provider==='multiple'?t('advisoryCannotInspect'):(ADVISER_LABELS[choice.model]||choice.model||choice.provider)+(choice.effort&&choice.effort!=='auto'?' · '+effortLabel(choice.effort):'');}
function renderAdvisoryStatus(){if(!config)return;const holder=$('advisory-choices');holder.replaceChildren();const providerGroup=make('div','advisory-group'),providerChips=make('div','team-chip-grid');providerGroup.append(make('strong','',t('advisoryChoose')));for(const provider of ['none','anthropic','deepseek'])providerChips.append(teamChip(provider,provider==='none'?t('advisoryNoProvider'):provider==='anthropic'?'Anthropic Claude':'DeepSeek',advisoryState.provider===provider,'provider'));providerGroup.append(providerChips);holder.append(providerGroup);if(['anthropic','deepseek'].includes(advisoryState.provider)){const provider=advisoryState.provider,models=config.advisory_models?.[provider]||[],modelGroup=make('div','advisory-group'),modelChips=make('div','team-chip-grid model-chips');modelGroup.append(make('strong','',t('advisoryModel')));if(advisoryState.model&&!models.includes(advisoryState.model)){const saved=teamChip(advisoryState.model,advisoryState.model,true,'model');saved.append(make('small','team-chip-provenance',t('advisoryCurrentOnly')));modelChips.append(saved);}for(const model of models){const chip=teamChip(model,ADVISER_LABELS[model]||model,advisoryState.model===model,'model');chip.append(make('small','team-chip-provenance',model));modelChips.append(chip);}modelGroup.append(modelChips);holder.append(modelGroup);const allowed=advisoryState.model==='claude-haiku-4-5-20251001'?['auto']:config.advisory_efforts?.[provider]||[],effortGroup=make('div','advisory-group'),effortChips=make('div','team-chip-grid');effortGroup.append(make('strong','',t('advisoryEffort')));for(const effort of allowed)effortChips.append(teamChip(effort,effort==='auto'?t('advisoryAuto'):effortLabel(effort),advisoryState.effort===effort,'effort'));effortGroup.append(effortChips);holder.append(effortGroup);$('advisory-status').textContent=t(config.advisory_key_available?.[provider]?'advisoryKeySeen':'advisoryKeyMissing')+' '+t('advisoryAccess');}else $('advisory-status').textContent=advisoryState.provider==='multiple'?t('advisoryCannotInspect'):t('advisoryNone');$('advisory-guide').href=`https://github.com/metapak/ustam-codex-orchestrator/blob/main/docs/external-providers.${lang==='tr'?'tr.':''}md`;}
function renderOtherEffect(){$('other-effect').textContent=selectedPreset==='economy'?t('economyEffect'):selectedPreset==='quota-saver'?t('quotaEffect'):selectedPreset==='custom'?t('customEffect'):t('otherHelp');}
function refreshModelOptions(card){const select=card.querySelector('select[data-kind=model]'),chosen=select.value||card.dataset.model||'';select.replaceChildren();for(const item of catalog?.models||[])select.append(new Option(item.label+' · '+t(item.origin==='local_cli'?'modelLocalBadge':'modelDocsBadge'),item.id));if(chosen&&!modelEntry(chosen)){const saved=chosen===config?.roles[card.dataset.role]?.model;const option=new Option(chosen+' · '+t(saved?'savedModelNotListed':'unlistedSelection'),chosen);option.dataset.unlisted='true';select.prepend(option);}select.value=chosen;card.dataset.model=chosen;const warning=card.querySelector('.model-warning');const entry=modelEntry(chosen);warning.textContent=entry?.origin==='documentation'?t('modelDocsBadge'):!entry&&chosen?t(chosen===config?.roles[card.dataset.role]?.model?'savedModelNotListed':'unlistedSelection'):'';warning.hidden=!warning.textContent;}
