function updateRoleLabels(){for(const card of $('roles').children){const role=card.dataset.role;card.querySelector('strong').textContent=t(ROLE_KEYS[role]);const spans=card.querySelectorAll('label span');spans[0].textContent=t('model');spans[1].textContent=t('depth');card.querySelector('select[data-kind=model]').setAttribute('aria-label',`${t(ROLE_KEYS[role])}: ${t('model')}`);card.querySelector('select[data-kind=effort]').setAttribute('aria-label',`${t(ROLE_KEYS[role])}: ${t('depth')}`);refreshModelOptions(card);refreshEffortOptions(card);}}
function fillRoles(roles){$('roles').replaceChildren();for(const [role,value] of Object.entries(roles)){const card=make('div','role-card');card.dataset.role=role;card.dataset.model=value.model;card.dataset.effort=value.effort;card.append(make('strong','',role));const fields=make('div','role-fields');const modelLabel=make('label');modelLabel.append(make('span','',t('model')));const modelSelect=make('select');modelSelect.dataset.kind='model';modelSelect.required=true;modelLabel.append(modelSelect);const effortLabel=make('label');effortLabel.append(make('span','',t('depth')));const effortSelect=make('select');effortSelect.dataset.kind='effort';effortLabel.append(effortSelect);fields.append(modelLabel,effortLabel);card.append(fields,make('small','model-warning'));$('roles').append(card);}updateRoleLabels();invalidate();}
function syncPreset(){for(const radio of document.querySelectorAll('input[name="profile-choice"]'))radio.checked=radio.value===selectedPreset;$('other-preset').value=['focused','balanced','quality'].includes(selectedPreset)?'':selectedPreset;}
function choosePreset(preset){if(!config?.presets[preset])return;selectedPreset=preset;manualOverride=Boolean(selectedTask);syncPreset();fillRoles(['focused','balanced','quality'].includes(preset)?recommendedRoles(preset,selectedTask):config.presets[preset]);applyPresetToTeam(preset);renderOtherEffect();renderDraftSummary();invalidate();}
async function loadSettings(initial=false){const data=await api('/api/settings');if(!catalog)catalog=await api('/api/models');config=data;token=data.csrf_token;advisoryState={...data.advisory_selection};$('destination').textContent=data.target;$('concurrency').value=data.concurrency;let actual={};for(const role of Object.keys(ROLE_KEYS)){const candidate=data.roles[role];actual[role]=candidate?.model?candidate:data.presets.focused[role];}selectedPreset=data.installed?(data.saved_preset||matchingPreset(actual)):'focused';if(!data.installed)selectedPreset=matchingPreset(actual);teamState=data.team.length?data.team.map(item=>({...item})):defaultTeam(data.team_count||data.concurrency,actual);$('team-count').value=teamState.length;selectedTask='';manualOverride=false;draftSnapshot=null;teamPage=0;syncPreset();fillRoles(actual);renderTeam();renderTaskCards();renderModelSource();renderAdvisoryStatus();renderOtherEffect();$('restore').disabled=!data.restore_available;$('uninstall-review').disabled=!data.uninstall_available;if(data.uninstall_supported===false)$('uninstall-status').textContent=t('uninstallUnsupported');$('save').textContent=t(data.installed?'teamSave':'teamInstalled');if(initial)recordActivity('settingsRead');}
function selectionPayload(){return {preset:manualOverride?'custom':selectedPreset,concurrency:Number($('concurrency').value),team_count:Number($('team-count').value),roles:roleValues(),team:teamState.map(item=>({...item})),advisory:{...advisoryState}};}
function settingLabel(value){if(!value?.model)return t('noInfo');const effort=value.effort||'';const key='effort'+effort[0]?.toUpperCase()+effort.slice(1);return value.model+' · '+(I18N[lang][key]||readable(effort));}
