function renderUsage(){if(!report)return;$('sample-badge').hidden=!report.sample_data;const available=report.status==='available'&&report.records_observed>0;$('usage-empty').hidden=available;$('usage-empty').textContent=!baseReport?.records_observed?t('sourceMissing'):t('usageEmpty');$('metrics').replaceChildren();const counterPresent=name=>report.records.some(record=>Object.hasOwn(record.usage,name));for(const [key,label] of [['total_tokens','totalText'],['input_tokens','readText'],['output_tokens','writtenText'],['cached_input_tokens','reusedText']]){const card=make('div','metric');card.append(make('span','metric-label',t(label)),make('strong','',available&&counterPresent(key)?number(report.totals[key]):t('noInfo')),make('span','metric-unit',t('tokenUnit')));$('metrics').append(card);}$('usage-help').textContent=available?t('cacheHelp'):'';$('source').textContent=t('sourceLocal')+' '+t('sourceSelected')+': '+readable(report.source_path);$('limits').textContent=t('limitsShort')+' '+t('chartSource');if(baseReport){optionList('project-filter',baseReport.groups.map(item=>item.project),'allProjects',shortProject);optionList('thread-filter',baseReport.groups.map(item=>item.thread),'allWork',workLabel);}renderUsageReel();renderCharts();}
function renderWork(){if(!report)return;const items=workGroups();$('work-list').replaceChildren();$('work-empty').hidden=items.length>0;$('work-empty').textContent=t('workEmpty');for(const item of items){const card=make('article','work-card');card.append(make('h3','',workLabel(item.thread)));const last=item.records.map(record=>record.timestamp).filter(value=>value&&value!=='unknown').sort().at(-1);card.append(make('p','',shortProject(item.project)+' · '+t('workDate')+': '+date(last)));card.append(make('span','amount',number(item.usage.total_tokens)+' '+t('tokenUnit')));const details=make('details');details.append(make('summary','',t('workDetails')));const dl=make('dl');for(const [term,value] of [[t('workId'),readable(item.thread)],[t('project'),readable(item.project)],[t('workStatus'),t('noInfo')],[t('workRecords',item.records.length),'']]){const dt=make('dt','',term);const dd=make('dd','',value);dl.append(dt,dd);}details.append(dl);for(const record of item.records){const bits=[date(record.timestamp),readable(record.model),t(ROLE_KEYS[record.role]||'noInfo'),t(record.semantics==='request'?'request':'cumulative'),number(record.usage.total_tokens)+' '+t('tokenUnit')];details.append(make('div','record-item',bits.join(' · ')));}card.append(details);$('work-list').append(card);}}
async function loadUsage(initial=false){const query=new URLSearchParams(new FormData($('filters')));if(initial){baseReport=await api('/api/usage?'+query);activeRoot=baseReport.orchestra?.scopes?.[0]?.id||'';}if(activeRoot)query.set('root',activeRoot);report=initial&&!activeRoot?baseReport:await api('/api/usage?'+query);renderUsage();renderOrchestra();renderWork();if(!initial)recordActivity('usageRefreshed');}
function selectTab(name){activeTab=name;for(const button of document.querySelectorAll('[data-tab]')){const active=button.dataset.tab===name;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active));$(button.dataset.tab).hidden=!active;}if(name==='settings')syncSettingsConductorMotion();else if(name==='usage')startConductorMotion();}
