$('team-inspector').addEventListener('click',event=>{const chip=event.target.closest('button[data-field]');if(!chip||!config)return;const field=chip.dataset.field,value=chip.dataset.value;if(selectedTeamSlot==='owner'){if(field==='duty')return;const card=$('roles').querySelector('[data-role=owner]');if(!card)return;const select=card.querySelector(`select[data-kind=${field}]`);if(!select)return;select.value=value;if(field==='model'){card.dataset.model=value;refreshEffortOptions(card,true);}selectedPreset='custom';syncPreset();renderOtherEffect();}else{const item=teamState.find(row=>row.slot===selectedTeamSlot);if(!item)return;item[field]=value;if(field==='duty'){const choice=roleValues()[value];item.model=choice.model;item.effort=choice.effort;}if(field==='model'){const efforts=modelEntry(item.model)?.efforts||[];if(efforts.length&&!efforts.includes(item.effort))item.effort=efforts[0];}}manualOverride=Boolean(selectedTask);renderTeam();renderDraftSummary();invalidate();});
$('advisory-choices').addEventListener('click',event=>{const chip=event.target.closest('button[data-field]');if(!chip||!config)return;const field=chip.dataset.field,value=chip.dataset.value;if(field==='provider'){if(value==='none')advisoryState={provider:'none',model:'',effort:''};else if(advisoryState.provider!==value||!advisoryState.model){const model=value==='anthropic'?'claude-sonnet-5-5':'deepseek-flash';advisoryState={provider:value,model,effort:'high'};}}else if(field==='model'){advisoryState.model=value;if(value==='claude-haiku-4-5-20251001')advisoryState.effort='auto';else if(advisoryState.effort==='auto'||!config.advisory_efforts?.[advisoryState.provider]?.includes(advisoryState.effort))advisoryState.effort='high';}else if(field==='effort')advisoryState.effort=value;renderAdvisoryStatus();invalidate();});
